"""
Btssm Interface
"""
from builtins import object
from taf.ul.trs_e2e_fw.lib.oam.btssm.commissioning import Commissioning
from taf.ul.trs_e2e_fw.lib.oam.btssm.alarms import Alarms
from taf.ul.trs_e2e_fw.lib.oam.btssm.btssm_setup import BtssmSetup
from taf.ul.trs_e2e_fw.lib.oam.btssm.certificate import Certificate
from taf.ul.trs_e2e_fw.lib.oam.btssm.cell_operations import CellOperations
from taf.ul.trs_e2e_fw.lib.oam.btssm.parameters import Parameters
from taf.ul.trs_e2e_fw.lib.oam.btssm.counters import Counters
from taf.ul.trs_e2e_fw.lib.oam.btssm.other_operations import OtherOperations


class BtssmInterface(object):
    """
    Btssm Interface
    """

    def __init__(self):
        pass

    def setup_oamops(self, **kwargs):
        """
        Function to setup oamops
        """
        BtssmSetup().setup_oamops(**kwargs)

    def teardown_oamops(self, **kwargs):
        """
        Function to teardown oamops
        """
        BtssmSetup().teardown_oamops(**kwargs)

    def certificate_configure(self, **kwargs):
        """
        Function to configure certificate
        """
        return Certificate().certificate_configure(**kwargs)

    def perform_commissioning(self, **kwargs):
        """
        Function to perform commissioning
        """
        return Commissioning().perform_commissioning(**kwargs)

    def perform_recommissioning(self, **kwargs):
        """
        Function to perfrom recommissioning
        """
        return Commissioning().perform_recommissioning(**kwargs)

    def verify_alarm(self, **kwargs):
        """
        Function verify alarm
        """
        return Alarms().verify_alarm(**kwargs)

    def verify_bts_status(self, **kwargs):
        """
        Function to Verify bts status
        """
        return CellOperations().verify_bts_status(**kwargs)

    def block_cell(self, **kwargs):
        """
        Function to block cell
        """
        return CellOperations().block_cell(**kwargs)

    def unblock_cell(self, **kwargs):
        """
        Function to unblock cell
        """
        return CellOperations().unblock_cell(**kwargs)

    def get_parameter(self, **kwargs):
        """
        Function to ger parameter
        """
        return Parameters().get_parameter(**kwargs)

    def pm_counters_start(self, **kwargs):
        """
        Function to start pm counters
        """
        return Counters().pm_counters_start(**kwargs)

    def verify_pm_counters(self, **kwargs):
        """
        Function to verify pm counters
        """
        return Counters().verify_pm_counters(**kwargs)

    def collect_snapshot(self, **kwargs):
        """
        Function to collect snapshot
        """
        return OtherOperations().collect_snapshot(**kwargs)

    def reset_bts(self, **kwargs):
        """
        Function to reset bts
        """
        return OtherOperations().reset_bts(**kwargs)

    def enable_ethernet_port_security(self, **kwargs):
        """
        Function to enable ethernet port security
        """
        return OtherOperations().enable_ethernet_port_security(**kwargs)

    def disable_ethernet_port_security(self, **kwargs):
        """
        Function to disable ethernet port security
        """
        return OtherOperations().disable_ethernet_port_security(**kwargs)

    def collect_im_snapshot(self, **kwargs):
        """
        Function to collect im snapshot
        """
        return OtherOperations().collect_im_snapshot(**kwargs)

    def generate_scf(self, **kwargs):
        """
        Function to generate scf
        """
        return OtherOperations().generate_scf(**kwargs)

    def user_account_manage(self, **kwargs):
        """
        Function to manage user account
        """
        return OtherOperations().user_account_manage(**kwargs)

    def perform_software_download_and_update(self, **kwargs):
        """
        Function to perform software download and update
        """
        return OtherOperations().perform_software_download_and_update(**kwargs)

    def get_parent_distnames_of_a_parameter(self, **kwargs):
        """
        Function to get parent distnames of a parameter
        """
        return Parameters().get_parent_distnames_of_a_parameter(**kwargs)

    def test_ipconnectivity(self, **kwargs):
        """
        Function to test ipconnectivity
        """
        return OtherOperations().test_ipconnectivity(**kwargs)

    def rollback_software(self, **kwargs):
        """
        Function to rollback software
        """
        return OtherOperations().rollback_software(**kwargs)

    def get_twamp_session_statistics(self, **kwargs):
        """
        Function to get twamp session statistics
        """
        return OtherOperations().get_twamp_statistics(**kwargs)

    def query_admin_infomodel(self, **kwargs):
        """
        Function to query admin infomodel
        """
        return Parameters().query_admin_infomodel(**kwargs)
